#ifndef FERRIS_FAKE_DOOR_BUS_H
#define FERRIS_FAKE_DOOR_BUS_H

#include "door_sensor.h"

#include <stddef.h>
#include <stdint.h>

enum { FAKE_DOOR_RESPONSE_CAPACITY = 16 };

typedef struct {
    DoorBusResult result;
    uint8_t bytes[2];
    size_t length;
} FakeDoorResponse;

typedef struct {
    FakeDoorResponse responses[FAKE_DOOR_RESPONSE_CAPACITY];
