                                                  DIAG_REASON_SENSOR,
                                                  0));
    }
    TEST_ASSERT(!diagnostics_record_transition(&diagnostics, 99U, 1, 2, DIAG_REASON_SENSOR, 0));
    TEST_ASSERT_EQ(1, diagnostics.overflow_count);
    TEST_PASS();
}

