        TEST_ASSERT_EQ(BUTTON_EVENT_NONE, button_update(&button, false, now + 40U));
        TEST_ASSERT_EQ(BUTTON_EVENT_RELEASE, button_update(&button, false, now + 65U));
        now += 100U;
    }
    TEST_ASSERT_EQ(4, press_count);
    TEST_PASS();
}

