                                   uint32_t timeout_ms) {
    (void)memory_address_size;
    (void)data;
    (void)size;
    (void)timeout_ms;
    i2c->last_address = device_address;
    i2c->last_memory_address = memory_address;
    return i2c->result;
}

uint32_t HAL_I2C_GetError(I2C_HandleTypeDef *i2c) {
