}

void ferris_stub_set_primask(uint32_t value) {
    ferris_stub_primask = value & 1U;
    ferris_stub_irq_disabled = ferris_stub_primask != 0U;
    ferris_stub_set_primask_count++;
}

void ferris_stub_nop(void) {
