    ferris_stub_disable_irq_count = 0U;
    ferris_stub_set_primask_count = 0U;
    ferris_stub_gpio_b.input[12] = GPIO_PIN_SET;

    ADC_HandleTypeDef adc = {
        .start_result = HAL_OK,
        .poll_result = HAL_OK,
        .value = 1700U,
    };
    TIM_HandleTypeDef pwm = {
        .autoreload = 999U,
        .pwm_start_result = HAL_OK,
        .base_start_result = HAL_OK,
    };
    TIM_HandleTypeDef scheduler = {
        .autoreload = 9U,
        .pwm_start_result = HAL_OK,
        .base_start_result = HAL_OK,
    };
    I2C_HandleTypeDef i2c = {
        .result = HAL_OK,
        .response = {DOOR_SENSOR_EXPECTED_ID, DOOR_SENSOR_LOCKED_MASK},
    };
    UART_HandleTypeDef uart = {
        .receive_result = HAL_OK,
        .transmit_result = HAL_OK,
    };
    IWDG_HandleTypeDef watchdog = {.refresh_result = HAL_OK};
    FerrisApp app;

    TEST_ASSERT(ferris_app_init(&app,
                                &adc,
                                &pwm,
                                TIM_CHANNEL_1,
                                &scheduler,
                                &i2c,
                                &uart,
                                &watchdog,
                                0U,
                                "test-reset"));
    TEST_ASSERT(app.initialized);
    TEST_ASSERT_EQ(1, pwm.pwm_start_count);
    TEST_ASSERT_EQ(1, scheduler.base_start_count);
    TEST_ASSERT_EQ(1, uart.receive_size);
    TEST_ASSERT_EQ(0, pwm.compare);
    TEST_ASSERT_EQ(GPIO_PIN_RESET, ferris_stub_gpio_b.output[13]);
    TEST_ASSERT(uart.transmitted_length > 0U);
    TEST_ASSERT(strstr((const char *)uart.transmitted, "STM32F103C8T6") != NULL);

    scheduler_tick(&app, 0U);
    TEST_ASSERT_EQ(FERRIS_STATE_SELF_TEST, app.controller.state);
    TEST_ASSERT_EQ(1, ferris_stub_disable_irq_count);
    TEST_ASSERT_EQ(1, ferris_stub_set_primask_count);
    TEST_ASSERT_EQ(0, ferris_stub_primask);

    app_events_isr_tick(&app.events);
    ferris_stub_primask = 1U;
    ferris_app_poll(&app, 10U);
    TEST_ASSERT_EQ(FERRIS_STATE_READY, app.controller.state);
    TEST_ASSERT_EQ(2, ferris_stub_disable_irq_count);
    TEST_ASSERT_EQ(2, ferris_stub_set_primask_count);
    TEST_ASSERT_EQ(1, ferris_stub_primask);
    ferris_stub_primask = 0U;

    ferris_stub_gpio_b.input[12] = GPIO_PIN_RESET;
    scheduler_tick(&app, 20U);
    scheduler_tick(&app, 50U);
    TEST_ASSERT_EQ(FERRIS_STATE_RUNNING, app.controller.state);
    TEST_ASSERT(pwm.compare > 0U);
    TEST_ASSERT_EQ(GPIO_PIN_SET, ferris_stub_gpio_b.output[13]);
    TEST_ASSERT(watchdog.refresh_count >= 4U);

    i2c.response[1] = 0U;
    scheduler_tick(&app, 100U);
    TEST_ASSERT_EQ(FERRIS_STATE_FAULT, app.controller.state);
    TEST_ASSERT_EQ(FERRIS_FAULT_DOOR_UNLOCKED, app.controller.fault_latch);
    TEST_ASSERT_EQ(0, pwm.compare);
    TEST_ASSERT_EQ(GPIO_PIN_RESET, ferris_stub_gpio_b.output[13]);
    TEST_ASSERT(strstr((const char *)uart.transmitted, "reason=fault") != NULL);
    TEST_PASS();
}

files.tests/test_ferris_controller.c:
#include "fault_supervisor.h"
#include "ferris_controller.h"
#include "test_support.h"

static FaultInputs healthy_inputs(void) {
    return (FaultInputs){
        .emergency_stop = false,
        .door_valid = true,
        .door_locked = true,
        .overloaded = false,
        .event_overflow = false,
        .health_complete = true,
    };
}

int main(void) {
    FaultSupervisor supervisor;
    fault_supervisor_init(&supervisor, 0x0FU);
    fault_supervisor_begin_cycle(&supervisor);
    fault_supervisor_mark_health(&supervisor, 0x01U);
    fault_supervisor_mark_health(&supervisor, 0x02U);
    TEST_ASSERT(!fault_supervisor_health_complete(&supervisor));
    fault_supervisor_mark_health(&supervisor, 0x0CU);
    TEST_ASSERT(fault_supervisor_health_complete(&supervisor));

    FaultInputs faults = healthy_inputs();
    faults.door_locked = false;
    faults.overloaded = true;
    FaultSnapshot snapshot = fault_supervisor_evaluate(&supervisor, &faults, 100U);
    TEST_ASSERT_EQ(FERRIS_FAULT_DOOR_UNLOCKED, snapshot.active);
    TEST_ASSERT_EQ(FERRIS_FAULT_DOOR_UNLOCKED, snapshot.latched);
    faults.door_locked = true;
    snapshot = fault_supervisor_evaluate(&supervisor, &faults, 110U);
    TEST_ASSERT_EQ(FERRIS_FAULT_OVERLOAD, snapshot.active);
    TEST_ASSERT_EQ(FERRIS_FAULT_DOOR_UNLOCKED, snapshot.latched);
    faults = healthy_inputs();
    TEST_ASSERT(fault_supervisor_clear_latch(&supervisor, &faults));

    FerrisController controller;
    ferris_controller_init(&controller);
    FerrisControllerInputs inputs = {
        .self_test_complete = false,
        .self_test_ok = false,
        .start_requested = false,
        .stop_requested = false,
        .reset_requested = false,
        .parked = false,
        .fault = {.active = FERRIS_FAULT_NONE, .latched = FERRIS_FAULT_NONE, .first_seen_ms = 0U},
    };
    TEST_ASSERT(ferris_controller_update(&controller, &inputs));
    TEST_ASSERT_EQ(FERRIS_STATE_SELF_TEST, controller.state);
    inputs.self_test_complete = true;
    inputs.self_test_ok = true;
    TEST_ASSERT(ferris_controller_update(&controller, &inputs));
    TEST_ASSERT_EQ(FERRIS_STATE_READY, controller.state);
    inputs.start_requested = true;
    TEST_ASSERT(ferris_controller_update(&controller, &inputs));
    TEST_ASSERT_EQ(FERRIS_STATE_RUNNING, controller.state);
    TEST_ASSERT_EQ(650, controller.requested_drive_permille);

    inputs.fault.active = FERRIS_FAULT_EMERGENCY_STOP;
    inputs.fault.latched = FERRIS_FAULT_EMERGENCY_STOP;
    TEST_ASSERT(ferris_controller_update(&controller, &inputs));
    TEST_ASSERT_EQ(FERRIS_STATE_FAULT, controller.state);
    TEST_ASSERT_EQ(0, controller.requested_drive_permille);

    for (int state = FERRIS_STATE_BOOT; state <= FERRIS_STATE_RESETTING; ++state) {
        ferris_controller_init(&controller);
        controller.state = (FerrisState)state;
        inputs = (FerrisControllerInputs){
            .fault = {.active = FERRIS_FAULT_EMERGENCY_STOP,
                      .latched = FERRIS_FAULT_EMERGENCY_STOP,
                      .first_seen_ms = 1U},
        };
        (void)ferris_controller_update(&controller, &inputs);
        TEST_ASSERT_EQ(FERRIS_STATE_FAULT, controller.state);
        TEST_ASSERT_EQ(0, controller.requested_drive_permille);
    }
    TEST_PASS();
}

