    const DoorReading reading = door_sensor_read(&bus, 100U, 5U);
    TEST_ASSERT(reading.valid && reading.locked);
    TEST_ASSERT_EQ(DOOR_SENSOR_ADDRESS << 1U, i2c.last_address);
