        .error = 0U,
        .response = {DOOR_SENSOR_EXPECTED_ID, DOOR_SENSOR_LOCKED_MASK},
        .last_address = 0U,
        .last_memory_address = 0U,
    };
    BoardStm32f1 board;
    board_stm32f1_init(&board, &adc, &timer, TIM_CHANNEL_1, &i2c);
    const BoardIo io = board_stm32f1_io(&board);
