        .receive_result = HAL_OK,
        .receive_buffer = NULL,
        .receive_size = 0U,
        .irq_count = 0U,
    };
    ferris_interrupts_bind(&events, &timer, &uart, &rx);
    TEST_ASSERT(ferris_uart_receive_start());
    TEST_ASSERT_EQ(1, uart.receive_size);
    HAL_TIM_IRQHandler(&timer);
    TEST_ASSERT_EQ(1, timer.irq_count);
