#include "analog_sensor.h"

#include <stddef.h>

bool analog_sensor_init(AnalogSensor *sensor,
                        uint16_t raw_min,
                        uint16_t raw_max,
                        size_t window_size) {
    if (sensor == NULL || raw_min >= raw_max || window_size == 0U ||
        window_size > ANALOG_FILTER_CAPACITY) {
        return false;
    }
    sensor->raw_min = raw_min;
    sensor->raw_max = raw_max;
    sensor->window_size = window_size;
    sensor->count = 0U;
    sensor->next = 0U;
    sensor->sum = 0U;
    for (size_t i = 0U; i < ANALOG_FILTER_CAPACITY; ++i) {
        sensor->samples[i] = 0U;
    }
    return true;
}

static uint16_t map_to_permille(uint32_t raw, uint16_t raw_min, uint16_t raw_max) {
    if (raw <= raw_min) {
        return 0U;
    }
    if (raw >= raw_max) {
        return 1000U;
    }
    const uint64_t numerator = ((uint64_t)raw - raw_min) * UINT64_C(1000);
    const uint32_t denominator = (uint32_t)raw_max - raw_min;
    return (uint16_t)((numerator + denominator / 2U) / denominator);
}

SensorReading analog_sensor_add(AnalogSensor *sensor, uint16_t raw, SensorError acquisition_error) {
    SensorReading reading = {.raw = raw, .value_permille = 0U, .valid = false, .error = acquisition_error};
    if (sensor == NULL || sensor->raw_min >= sensor->raw_max || sensor->window_size == 0U ||
        sensor->window_size > ANALOG_FILTER_CAPACITY) {
        reading.error = SENSOR_ERROR_CALIBRATION;
        return reading;
    }
    if (acquisition_error != SENSOR_ERROR_NONE) {
        return reading;
    }
    if (sensor->count < sensor->window_size) {
        sensor->samples[sensor->next] = raw;
        sensor->sum += raw;
        sensor->count++;
    } else {
        sensor->sum -= sensor->samples[sensor->next];
        sensor->samples[sensor->next] = raw;
        sensor->sum += raw;
    }
    sensor->next = (sensor->next + 1U) % sensor->window_size;
    if (sensor->count == 0U) {
        reading.error = SENSOR_ERROR_EMPTY_FILTER;
        return reading;
    }
    const uint32_t average = (sensor->sum + (uint32_t)sensor->count / 2U) /
                             (uint32_t)sensor->count;
    reading.value_permille = map_to_permille(average, sensor->raw_min, sensor->raw_max);
    reading.valid = true;
    reading.error = SENSOR_ERROR_NONE;
    return reading;
}

void overload_init(OverloadDetector *detector,
                   uint16_t enter_threshold,
                   uint16_t exit_threshold) {
    if (detector == NULL) {
        return;
    }
    detector->enter_threshold = enter_threshold;
    detector->exit_threshold = exit_threshold;
    detector->overloaded = false;
}

bool overload_update(OverloadDetector *detector, const SensorReading *reading, bool *changed) {
    if (changed != NULL) {
        *changed = false;
    }
    if (detector == NULL || reading == NULL || !reading->valid ||
        detector->exit_threshold >= detector->enter_threshold) {
        return detector != NULL && detector->overloaded;
    }
    const bool before = detector->overloaded;
    if (!before && reading->value_permille >= detector->enter_threshold) {
        detector->overloaded = true;
    } else if (before && reading->value_permille <= detector->exit_threshold) {
        detector->overloaded = false;
    }
    if (changed != NULL) {
        *changed = before != detector->overloaded;
    }
    return detector->overloaded;
}

files.Core/Src/app_events.c:
#include "app_events.h"

#include <limits.h>
#include <stddef.h>

static uint32_t saturating_increment_u32(uint32_t value) {
    return value == UINT32_MAX ? UINT32_MAX : value + 1U;
}

void app_events_init(AppEvents *events,
                     AppEventCriticalFn enter_critical,
                     AppEventCriticalFn exit_critical,
                     void *critical_context) {
    if (events == NULL) {
        return;
    }
    events->tick_count = 0U;
    events->fault_bits = 0U;
    events->dropped_events = 0U;
    events->enter_critical = enter_critical;
    events->exit_critical = exit_critical;
    events->critical_context = critical_context;
}

void app_events_isr_tick(AppEvents *events) {
    if (events == NULL) {
        return;
    }
    if (events->tick_count == UINT16_MAX) {
        events->dropped_events = saturating_increment_u32(events->dropped_events);
    } else {
        events->tick_count++;
    }
}

void app_events_isr_fault(AppEvents *events, uint32_t fault_bits) {
    if (events != NULL) {
        events->fault_bits |= fault_bits;
    }
}

AppEventSnapshot app_events_take(AppEvents *events) {
    AppEventSnapshot snapshot = {0U, 0U, 0U};
    if (events == NULL) {
        return snapshot;
    }
    if (events->enter_critical != NULL) {
        events->enter_critical(events->critical_context);
    }
    snapshot.tick_count = events->tick_count;
    snapshot.fault_bits = events->fault_bits;
    snapshot.dropped_events = events->dropped_events;
    events->tick_count = 0U;
    events->fault_bits = 0U;
    events->dropped_events = 0U;
    if (events->exit_critical != NULL) {
        events->exit_critical(events->critical_context);
    }
    return snapshot;
}

files.Core/Src/app_time.c:
#include "app_time.h"

#include <stddef.h>

uint32_t app_elapsed(uint32_t now_ms, uint32_t since_ms) {
    return now_ms - since_ms;
}

bool app_due(uint32_t now_ms, uint32_t since_ms, uint32_t interval_ms) {
    return app_elapsed(now_ms, since_ms) >= interval_ms;
}

void heartbeat_init(Heartbeat *heartbeat, uint32_t now_ms, uint32_t period_ms) {
    if (heartbeat == NULL) {
        return;
    }
    heartbeat->changed_at_ms = now_ms;
    heartbeat->period_ms = period_ms;
    heartbeat->output_on = false;
}

bool heartbeat_update(Heartbeat *heartbeat, uint32_t now_ms) {
    if (heartbeat == NULL || heartbeat->period_ms == 0U ||
        !app_due(now_ms, heartbeat->changed_at_ms, heartbeat->period_ms)) {
        return false;
    }
    const uint32_t periods = app_elapsed(now_ms, heartbeat->changed_at_ms) /
                             heartbeat->period_ms;
    heartbeat->changed_at_ms += periods * heartbeat->period_ms;
    if ((periods & 1U) != 0U) {
        heartbeat->output_on = !heartbeat->output_on;
    }
    return true;
}

