#include "uart_rx.h"

#include <stdio.h>
#include <string.h>

void uart_rx_init(UartRx *rx) {
    if (rx == NULL) {
        return;
    }
    rx->head = 0U;
    rx->tail = 0U;
    rx->dropped_bytes = 0U;
    rx->reported_dropped_bytes = 0U;
    rx->line[0] = '\0';
    rx->line_length = 0U;
    rx->discarding_line = false;
    rx->previous_was_cr = false;
}

bool uart_rx_isr_push(UartRx *rx, uint8_t byte) {
    if (rx == NULL) {
        return false;
    }
    const uint16_t next = (uint16_t)((rx->head + 1U) % UART_RX_RING_CAPACITY);
    if (next == rx->tail) {
        if (rx->dropped_bytes != UINT32_MAX) {
            rx->dropped_bytes++;
        }
        return false;
    }
    rx->ring[rx->head] = byte;
    rx->head = next;
    return true;
}

static UartCommandType parse_command(const char *line) {
    if (strcmp(line, "status") == 0) {
        return UART_COMMAND_STATUS;
    }
    if (strcmp(line, "stop") == 0) {
        return UART_COMMAND_STOP;
    }
    if (strcmp(line, "reset") == 0) {
        return UART_COMMAND_RESET;
    }
    return UART_COMMAND_UNKNOWN;
}

static void set_command(UartCommand *command, UartCommandType type, const char *text) {
    command->type = type;
    if (text == NULL) {
        command->text[0] = '\0';
        return;
    }
    (void)snprintf(command->text, sizeof(command->text), "%s", text);
}

bool uart_rx_poll(UartRx *rx, UartCommand *command) {
    if (rx == NULL || command == NULL) {
        return false;
    }
    if (rx->reported_dropped_bytes != rx->dropped_bytes) {
        rx->reported_dropped_bytes = rx->dropped_bytes;
        set_command(command, UART_COMMAND_RX_OVERFLOW, "rx-overflow");
        return true;
    }
    while (rx->tail != rx->head) {
        const char byte = (char)rx->ring[rx->tail];
        rx->tail = (uint16_t)((rx->tail + 1U) % UART_RX_RING_CAPACITY);

        if (byte == '\n' && rx->previous_was_cr) {
            rx->previous_was_cr = false;
            continue;
        }
        const bool is_newline = byte == '\r' || byte == '\n';
        rx->previous_was_cr = byte == '\r';
        if (!is_newline) {
            if (rx->discarding_line) {
                continue;
            }
            if (rx->line_length + 1U >= UART_RX_LINE_CAPACITY) {
                rx->discarding_line = true;
            } else {
                rx->line[rx->line_length++] = byte;
                rx->line[rx->line_length] = '\0';
            }
            continue;
        }
        if (rx->discarding_line) {
            rx->discarding_line = false;
            rx->line_length = 0U;
            rx->line[0] = '\0';
            set_command(command, UART_COMMAND_LINE_TOO_LONG, "line-too-long");
            return true;
        }
        if (rx->line_length == 0U) {
            continue;
        }
        set_command(command, parse_command(rx->line), rx->line);
        rx->line_length = 0U;
        rx->line[0] = '\0';
        return true;
    }
    return false;
}

files.tests/fake_door_bus.c:
#include "fake_door_bus.h"

#include <string.h>

static DoorBusResult fake_read(void *context,
                               uint8_t address,
                               uint8_t register_address,
                               uint8_t *output,
                               size_t capacity,
                               size_t *received,
                               uint32_t timeout_ms) {
    FakeDoorBus *fake = context;
    if (received != NULL) {
        *received = 0U;
    }
    if (fake == NULL || output == NULL || received == NULL || fake->next >= fake->count) {
        return DOOR_BUS_IO_ERROR;
    }
    fake->last_address = address;
    fake->last_register = register_address;
    fake->last_timeout_ms = timeout_ms;
    const FakeDoorResponse response = fake->responses[fake->next++];
    if (response.result != DOOR_BUS_OK) {
        return response.result;
    }
    const size_t copied = response.length < capacity ? response.length : capacity;
    memcpy(output, response.bytes, copied);
    *received = copied;
    return DOOR_BUS_OK;
}

static DoorBusResult fake_write(void *context,
                                uint8_t address,
                                uint8_t register_address,
                                const uint8_t *data,
                                size_t length,
                                uint32_t timeout_ms) {
    FakeDoorBus *fake = context;
    if (fake == NULL || data == NULL || length > sizeof(fake->last_written)) {
        return DOOR_BUS_IO_ERROR;
    }
    fake->last_address = address;
    fake->last_register = register_address;
    fake->last_timeout_ms = timeout_ms;
    memcpy(fake->last_written, data, length);
    fake->last_written_length = length;
    return fake->write_result;
}

void fake_door_bus_init(FakeDoorBus *fake) {
    if (fake != NULL) {
        memset(fake, 0, sizeof(*fake));
        fake->write_result = DOOR_BUS_OK;
    }
}

bool fake_door_bus_add(FakeDoorBus *fake,
                       DoorBusResult result,
                       uint8_t device_id,
                       uint8_t status,
                       size_t length) {
    if (fake == NULL || fake->count >= FAKE_DOOR_RESPONSE_CAPACITY || length > 2U) {
        return false;
    }
    fake->responses[fake->count++] = (FakeDoorResponse){
        .result = result,
        .bytes = {device_id, status},
        .length = length,
    };
    return true;
}

DoorBus fake_door_bus_interface(FakeDoorBus *fake) {
    const DoorBus bus = {.read = fake_read, .write = fake_write, .context = fake};
    return bus;
}

